1	// Entire CLI extension for Pi
2	// Auto-generated by `entire enable --agent pi`
3	// Do not edit manually — changes will be overwritten on next install.
4	//
5	// Forwards Pi lifecycle events to `entire hooks pi <event>` so Entire can
6	// create checkpoints, capture transcripts, and offer rewind/resume.
7	//
8	// ENTIRE_CMD is replaced at install time by Entire's installer.
9	
10	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
11	import { execFile } from "node:child_process";
12	
13	export default function (pi: ExtensionAPI) {
14	  // A Pi subagent is a nested `pi` process (subagent extensions spawn one per task
15	  // with cwd inside the project, where Pi auto-discovers this same project-local
16	  // extension), so it would otherwise forward its own lifecycle as the user's
17	  // session. Mark this process so any Pi it spawns knows it is nested.
18	  //
19	  // WARNING: Entire's own hook subprocesses inherit this marker from the parent, so
20	  // the CLI side must never treat it as a skip signal — it would disable tracking
21	  // for everyone. See docs/architecture/agent-guide.md.
22	  const nested = Boolean(process.env.ENTIRE_PI_NESTED);
23	  process.env.ENTIRE_PI_NESTED = "1";
24	
25	  const ENTIRE_CMD = 'entire';
26	  let pendingSkillEvents: Array<{ skill_name: string; invocation: string; timestamp: string }> = [];
27	
28	  // fireHook pipes data to `entire hooks pi <hookName>` and resolves with the
29	  // hook's stdout (empty string on any failure). Most hooks ignore the return;
30	  // before_agent_start uses it to apply a model-context injection.
31	  function fireHook(hookName: string, data: Record<string, unknown>): Promise<string> {
32	    return new Promise((resolve) => {
33	      try {
34	        const child = execFile(
35	          "sh",
36	          ["-c", `${ENTIRE_CMD} hooks pi ${hookName}`],
37	          { timeout: 10000, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
38	          (_err, stdout) => resolve(typeof stdout === "string" ? stdout : ""),
39	        );
40	        child.stdin?.end(JSON.stringify(data));
41	      } catch {
42	        // best effort — never block the agent on a hook failure
43	        resolve("");
44	      }
45	    });
46	  }
47	
48	  // parseInjectedContext scans a hook's stdout for Entire's injection envelope
49	  // ({"inject_context":"..."}) and returns the text to inject, or null.
50	  function parseInjectedContext(stdout: string): string | null {
51	    if (!stdout) return null;
52	    for (const line of stdout.split("\n")) {
53	      const trimmed = line.trim();
54	      if (!trimmed.startsWith("{")) continue;
55	      try {
56	        const parsed = JSON.parse(trimmed) as { inject_context?: unknown };
57	        if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
58	          return parsed.inject_context;
59	        }
60	      } catch {
61	        // not our envelope — ignore
62	      }
63	    }
64	    return null;
65	  }
66	
67	  function parseSkillInvocation(text: string): { skill_name: string; invocation: string } | null {
68	    const match = text.trimStart().match(/^\/skill:([a-z0-9][a-z0-9-]{0,63})(?:\s|$)/);
69	    if (!match) return null;
70	    const invocation = text.trimStart().split(/\s+/, 1)[0] ?? `/skill:${match[1]}`;
71	    return { skill_name: match[1], invocation };
72	  }
73	
74	  // Agent-driven bash subprocesses inherit a real TTY but cannot answer
75	  // hook prompts. Disable git/Entire terminal prompts for bash calls so
76	  // Entire treats agent-driven commits as non-interactive.
77	  //
78	  // Registered even when nested: a nested Pi is non-interactive by construction
79	  // while still inheriting the parent's TTY, and Entire's git hooks live in
80	  // .git/hooks independently of this extension, so a nested subagent that commits
81	  // needs this hardening at least as much as the parent does.
82	  pi.on("tool_call", async (event) => {
83	    if (event.toolName !== "bash") return;
84	    const input = event.input as { command?: string };
85	    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
86	      return;
87	    }
88	    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
89	  });
90	
91	  // Everything below forwards session lifecycle to Entire, which only the
92	  // top-level Pi may do.
93	  if (nested) return;
94	
95	  pi.on("input", async (event) => {
96	    const skill = parseSkillInvocation(event.text);
97	    if (skill) {
98	      pendingSkillEvents.push({ ...skill, timestamp: new Date().toISOString() });
99	    }
100	    return { action: "continue" };
101	  });
102	
103	  pi.on("session_start", async (_event, ctx) => {
104	    await fireHook("session_start", {
105	      type: "session_start",
106	      cwd: ctx.cwd,
107	      session_file: ctx.sessionManager.getSessionFile(),
108	    });
109	  });
110	
111	  pi.on("before_agent_start", async (event, ctx) => {
112	    const skillEvents = pendingSkillEvents;
113	    pendingSkillEvents = [];
114	    const stdout = await fireHook("before_agent_start", {
115	      type: "before_agent_start",
116	      cwd: ctx.cwd,
117	      session_file: ctx.sessionManager.getSessionFile(),
118	      prompt: event.prompt,
119	      skill_events: skillEvents,
120	    });
121	    const injected = parseInjectedContext(stdout);
122	    if (injected) {
123	      // Inject a hidden, persistent message so the model learns about Entire.
124	      // display:false keeps it out of the user-facing transcript while still
125	      // sending it to the LLM. Entire emits this at most once per session.
126	      return {
127	        message: {
128	          customType: "entire-context",
129	          content: injected,
130	          display: false,
131	        },
132	      };
133	    }
134	  });
135	
136	  pi.on("agent_end", async (_event, ctx) => {
137	    await fireHook("agent_end", {
138	      type: "agent_end",
139	      cwd: ctx.cwd,
140	      session_file: ctx.sessionManager.getSessionFile(),
141	    });
142	  });
143	
144	  pi.on("session_shutdown", async () => {
145	    await fireHook("session_shutdown", { type: "session_shutdown" });
146	  });
147	}
